    def path(self, name: str) -> str:
        return os.path.join(self.directory, name)

    def read_bytes(self, name: str, required: bool) -> bytes:
        try:
            with open(self.path(name), "rb") as fh:
                return fh.read()
        except FileNotFoundError:
            if required:
                raise usage("{}: file not found".format(name))
            return b""
        except OSError as exc:
            raise usage("{}: cannot read: {}".format(name, exc.strerror or exc))

    def read_text(self, name: str, required: bool = False) -> str:
        data = self.read_bytes(name, required)
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise usage("{}: not valid UTF-8 (byte {})".format(name, exc.start))

    def parsed(self, name: str, parse, *args):
        text = self.read_text(name, required=(name == CATALOG))
        try:
            return parse(text, *args)
        except ParseError as exc:
            raise refuse("{}: {}".format(name, exc))

    def catalog(self):
        return self.parsed(CATALOG, parse_catalog)

    def movements(self, catalog):
        return self.parsed(MOVEMENTS, parse_movements, catalog)

    def orders(self, catalog):
        return self.parsed(ORDERS, parse_orders, catalog)

    def append_lines(self, lines: List[str]) -> None:
        path = self.path(MOVEMENTS)
        existing = self.read_bytes(MOVEMENTS, required=False)
        prefix = "\n" if existing and not existing.endswith(b"\n") else ""
        payload = (prefix + "".join(line + "\n" for line in lines)).encode("utf-8")
        try:
            with open(path, "ab") as fh:
                fh.write(payload)
        except OSError as exc:
            raise usage("{}: cannot write: {}".format(MOVEMENTS, exc.strerror or exc))


